async function loadQuota(force){
  try{
    QUOTA = await jget('/api/quota' + (force ? '?force=1' : ''));
    if(QUOTA.accounts) ACCTS = QUOTA.accounts;
  }catch(e){
    QUOTA = {error: 'Failed to read'};
  }
  refreshChip();
  const pop = $('#acctPop');
  if(pop && !pop.hidden) renderPop();
}

