function bindPop(){
  const pop = $('#acctPop');
  pop.querySelectorAll('.ap-item').forEach(it => {
    it.onclick = async () => {
      const i = +it.dataset.idx;
      if((ACCTS[i] || {}).active) return;
      it.style.opacity = .45;
      const d = await jpost('/api/account/switch', {index: i});
      if(d.error){ it.style.opacity = 1; alert(d.error); return; }
      QUOTA = d;
      if(d.accounts) ACCTS = d.accounts;
      refreshChip(); renderPop();
      log(['Switched to account: ' + ((ACCTS.find(a => a.active) || {}).label || '')]);
    };
  });

  const req = $('#apReq');
  if(req) req.onclick = async () => {
    const email = ($('#apEmail').value || '').trim();
    if(!email){ $('#apEmail').focus(); return; }
    req.disabled = true; req.textContent = 'Requesting…';
    try{
      const d = await jpost('/api/account/request', {email});
      if(d.error){ alert(d.error); return; }
      $('#apKey').value = d.api_key || '';
      $('#apLabel').value = email;
      log(['Requested a new key for ' + email + ' (…' + (d.api_key || '').slice(-4) + ')',
           'Now open the email and click "Activate your OpenAlex API key", then come back and click Add']);
      alert('Key generated and filled into the field below:\n\n' + d.api_key
        + '\n\nBut you must activate it first: check ' + email + ' for an email titled'
        + '\n\"Activate your OpenAlex API key\" and click the button inside.'
        + '\nThen come back and click Add.');
    }catch(e){ alert(String(e)); }
    finally{ req.disabled = false; req.textContent = 'Request'; }
  };

  const save = $('#apSave');
  if(save) save.onclick = async () => {
    const key = ($('#apKey').value || '').trim();
    if(!key){ $('#apKey').focus(); return; }
    save.disabled = true; save.textContent = 'Verifying…';
    try{
      const d = await jpost('/api/account/add', {
        api_key: key,
        email: ($('#apEmail').value || '').trim(),
        label: ($('#apLabel').value || '').trim()
      });
      if(d.error){ alert(d.error); return; }
      QUOTA = d;
      if(d.accounts) ACCTS = d.accounts;
      refreshChip(); renderPop();
      log(['Added and switched to the new account' + (QUOTA.error ? ' ⚠ ' + QUOTA.error : '')]);
    }finally{ save.disabled = false; save.textContent = 'Add'; }
  };

  const rf = $('#apRefresh');
  if(rf) rf.onclick = ev => { ev.preventDefault(); loadQuota(true); };
  const su = $('#apSignup');
  if(su) su.onclick = ev => {
    ev.preventDefault();
    const ok = QUOTA && QUOTA.signup ? QUOTA.signup : 'https://openalex.org/settings/api';
    openUrl(ok);
  };
}

