let CITEBUSY = false;

async function doCites(){
  const pop = $('#citePop'), go = $('#citeGo');
  const idx = [...sel];
  if(!idx.length || CITEBUSY) return;
  CITEBUSY = true;
  if(go){ go.disabled = true; go.textContent = 'Expanding…'; }
  // hide the popup right away: otherwise clicking a direction chip while waiting redraws the whole popup,
  // the "Start expansion" button becomes clickable again → a second request can fire concurrently and clobber the "Back" target
  if(pop) pop.hidden = true;
  log(['Citation expansion: querying Semantic Scholar (about ten seconds, do not close the window)…']);
  try{
    const out = await jpost('/api/cites', {indices: idx, direction: CITEDIR, limit: 200});
    if(out.error){
      alert(out.error);
      log(['✗ Citation expansion failed: ' + String(out.error).split('\n')[0]]);
      renderCitePop();                 // reopen it so the user can retry with another direction
      const pp = $('#citePop'); if(pp) pp.hidden = false;
      return;
    }
    render(out.results);
    const b = $('#btnBack'); if(b) b.hidden = false;
    const st = out.stats || {};
    const dirTxt = {both:'Both directions', citations:'Cited by', references:'References'}[CITEDIR] || '';
    log([`Citation expansion (${dirTxt}): ${st.seeds || 0} seeds → ${out.n} items after dedup`
         + (st.citations ? ` · Forward ${st.citations}` : '')
         + (st.references ? ` · Backward ${st.references}` : '')
         + (st.dup ? ` · Duplicates merged ${st.dup}` : ''),
         (st.ref_empty_seeds && st.ref_empty_seeds >= (st.seeds || 1) && CITEDIR !== 'citations'
           ? '⚠ Semantic Scholar has no reference list for these seeds (common with Elsevier / Wiley),'
             + 'OA papers like MDPI usually do have one'
           : ''),
         'Papers tagged "Co-seed N" are linked by several seeds at once, look at those first; you can still download and export them after selecting']
         .filter(Boolean));
  }catch(e){
    alert('Expansion failed: ' + e);
    renderCitePop();
    const pp = $('#citePop'); if(pp) pp.hidden = false;
  }finally{
    CITEBUSY = false;
  }
}

$('#btnCites').onclick = () => {
